    let mut r = Rectangle::new(2, 3);
    println!("{}", r); // Rectangle: (2, 3)

    r.change_width(5);
    println!("{}", r); // Rectangle: (5, 3)

    println!("Area: {}", r.area()); // Area: 15
}

